// 1. 每任务一个虚拟线程
try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    for (int i = 0; i < 100_000; i++) {
        int taskId = i;
        executor.submit(() -> {
            // 适合等待型 I/O；真实系统还要限制 DB 连接和下游 QPS
            Thread.sleep(Duration.ofSeconds(1));
            return "Result-" + taskId;
        });
    }
}

// 2. 不要用虚拟线程池大小表达并发保护
// 应该用连接池、Semaphore、限流器或队列保护外部资源
Semaphore dbPermits = new Semaphore(200);
try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    executor.submit(() -> {
        dbPermits.acquire();
        try {
            return queryDatabase();
        } finally {
            dbPermits.release();
        }
    });
}

// 3. Java 21-23 避免 synchronized 中阻塞；Java 24+ 有 JEP 491 改进
synchronized (lock) {
    updateSharedStateOnly(); // 持锁区尽量短，不做慢 I/O
}
